def gen(rng):
    def fmt(a):
        return f"{len(a)}\n" + ' '.join(map(str, a))

    tests = [fmt([0]), fmt([7, 7, 7, 7]), fmt([1, 2, 3, 4, 5, 6]), fmt([6, 5, 4, 3, 2, 1]), fmt([0, 10**9]), fmt([10**9, 0]), fmt([3, 1, 4, 1, 5, 9, 2, 6])]
    for n in (2, 3, 4, 5, 6, 7, 8):
        for vmax in (2, 5, 10**9):
            tests.append(fmt([rng.randint(0, vmax) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 5) for _ in range(n)]))
    tests.append(fmt(list(range(n))))
    tests.append(fmt([i // 3 for i in range(n)]))
    tests.append(fmt([rng.randint(0, 10**9) if i % 2 else 10**9 for i in range(n)]))
    return tests
